            reject: [{ re: '\\b(climbed|rose|increased|grew|went up)\\b', hint: 'Check the dates: 2026 and 2030 have not been recorded. Is this a fact or a forecast?' }, { re: 'projecting|expecting|predicting|forecasting', hint: 'Somebody else makes the forecast, so this verb is passive: "is …-ed to".' }, { re: 'fall|drop|declin|decreas', hint: 'Follow the streaming line after 2022. Up or down?' }, { re: '^(they|their) |are (projected|expected|forecast|predicted)', hint: 'The subject is one thing. Check the pronoun and the verb.' }, { re: '\\b(to|by)$', hint: 'Stop after the verb: the next step adds the figure.' }],
